{
      "name": "Вода",
      "description": "Примерная дневная цель воды.",
      "inputs": "Вес, тренировка/активность.",
      "formula": "Вода мл = вес × 30–35. В день тренировки можно добавить 500–1000 мл."
    }

{
      "name": "Клетчатка",
      "description": "Ориентир по клетчатке в питании.",
      "inputs": "Калории.",
      "formula": "Клетчатка г = ккал / 1000 × 14."
    }

{
      "name": "1ПМ Epley",
      "description": "Расчёт примерного одноповторного максимума.",
      "inputs": "Рабочий вес, количество повторений.",
      "formula": "1ПМ = вес × (1 + повторения / 30)."
    }

{
      "name": "1ПМ Brzycki",
      "description": "Альтернативная формула одноповторного максимума.",
      "inputs": "Рабочий вес, количество повторений.",
      "formula": "1ПМ = вес × 36 / (37 − повторения). Лучше применять примерно до 10–12 повторений."
    }

{
      "name": "Рабочий вес от 1ПМ",
      "description": "Подбор веса по проценту от максимума.",
      "inputs": "1ПМ, процент нагрузки.",
      "formula": "Рабочий вес = 1ПМ × процент / 100."
    }

{
      "name": "Тренировочный объём упражнения",
      "description": "Общая нагрузка в одном упражнении.",
      "inputs": "Подходы, повторения, вес.",
      "formula": "Объём = подходы × повторения × вес."
    }

{
      "name": "Общий объём тренировки",
      "description": "Суммарная нагрузка за тренировку.",
      "inputs": "Объёмы всех упражнений.",
      "formula": "Общий объём = сумма объёма всех упражнений."
    }

{
      "name": "Средний рабочий вес",
      "description": "Средний вес на одно повторение.",
      "inputs": "Общий объём, общее количество повторений.",
      "formula": "Средний вес = общий объём / общее количество повторений."
    }

{
      "name": "Плотность тренировки",
      "description": "Нагрузка относительно времени тренировки.",
      "inputs": "Общий объём, длительность тренировки.",
      "formula": "Плотность = общий объём / длительность в минутах."
    }

{
      "name": "Максимальный пульс",
      "description": "Приближённая оценка максимальной ЧСС.",
      "inputs": "Возраст.",
      "formula": "HRmax = 220 − возраст."
    }

{
      "name": "Пульсовые зоны",
      "description": "Диапазоны пульса для разной интенсивности.",
      "inputs": "HRmax, проценты зон.",
      "formula": "Нижняя граница = HRmax × нижний %. Верхняя граница = HRmax × верхний %. Например 50–70%."
    }

{
      "name": "Пульсовые зоны Карвонена",
      "description": "Зоны пульса с учётом пульса покоя.",
      "inputs": "Возраст, пульс покоя, интенсивность.",
      "formula": "HRmax = 220 − возраст. Резерв = HRmax − пульс покоя. Целевая ЧСС = резерв × интенсивность + пульс покоя."
    }

{
      "name": "Калории за активность по MET",
      "description": "Оценка расхода калорий за тренировку.",
      "inputs": "MET активности, вес, длительность.",
      "formula": "ккал = MET × 3.5 × вес / 200 × минуты."
    }

{
      "name": "Темп бега",
      "description": "Время на 1 км.",
      "inputs": "Дистанция, время.",
      "formula": "Темп = время / дистанция. Например 30 минут / 5 км = 6:00 мин/км."
    }

{
      "name": "Скорость бега",
      "description": "Средняя скорость движения.",
      "inputs": "Дистанция, время.",
      "formula": "Скорость км/ч = дистанция км / время в часах."
    }

{
      "name": "Дистанция по шагам",
      "description": "Примерная дистанция по количеству шагов.",
      "inputs": "Количество шагов, длина шага.",
      "formula": "Дистанция м = шаги × длина шага м."
    }

{
      "name": "Калории по шагам",
      "description": "Грубая оценка расхода калорий при ходьбе.",
      "inputs": "Вес, дистанция.",
      "formula": "ккал ≈ вес кг × дистанция км × 0.5–0.8. Точнее использовать MET."
    }

{
      "name": "Длительность сна",
      "description": "Сколько часов пользователь спал.",
      "inputs": "Время засыпания, время пробуждения.",
      "formula": "Сон = время пробуждения − время засыпания. Если переход через полночь, добавить 24 часа."
    }

{
      "name": "Дефицит сна",
      "description": "Недобор сна относительно цели.",
      "inputs": "Фактический сон, целевой сон.",
      "formula": "Дефицит = целевой сон − фактический сон. Если результат меньше 0, дефицит = 0."
    }

{
      "name": "Средний сон",
      "description": "Средняя длительность сна за период.",
      "inputs": "Сумма часов сна, количество дней.",
      "formula": "Средний сон = сумма часов сна / количество дней."
    }
